import { useState, useRef } from "react";
import clsx from "clsx";
import { useGSAP } from "../hooks/useGSAP";
import { ParticleCanvas, Typewriter, SkillBar, ParallaxElement, ScrollReveal } from "../components/Shared";
import { DevBadge } from "../components/DeveloperMode";
import { PROJECTS, SKILLS, TECH, SERVICES, TIMELINE, CONTACT_INFO } from "../data/content";
import "./ForestLayout.css";

function ForestClearingCard({ project, index, theme }) {
  return (
    <article className="forest-clearing-card">
      <div
        className="forest-clearing-visual"
        style={{ background: project.image ? `url(${project.image}) center/cover no-repeat` : project.cardBg }}
      >
        {project.liveUrl && (
          <div className="forest-clearing-live">
            <span />
            <span>Live</span>
          </div>
        )}
      </div>
      <div className="forest-clearing-body">
        <span className="forest-clearing-index">Clearing {String(index + 1).padStart(2, "0")}</span>
        <h3>{project.title}</h3>
        <p>{project.longDesc}</p>
        <div className="forest-clearing-tags">
          {project.stack.map((tech) => (
            <span key={tech}>{tech}</span>
          ))}
        </div>
        {project.liveUrl && (
          <a className="forest-clearing-link" href={project.liveUrl} target="_blank" rel="noopener noreferrer">
            Visit project →
          </a>
        )}
      </div>
    </article>
  );
}

export function ForestLayout({ theme, devMode, scrollTo, tIdx, setTIdx, sel, setSel, sent, setSent, form, setForm }) {
  const heroRef = useRef(null);
  const heroTitleRef = useRef(null);
  const heroBadgeRef = useRef(null);
  const heroSubRef = useRef(null);
  const heroCtaRef = useRef(null);
  const aboutRef = useRef(null);
  const servicesRef = useRef(null);
  const timelineRef = useRef(null);
  const contactRef = useRef(null);
  const clearingsRef = useRef(null);
  const clearingsRailRef = useRef(null);
  const clearingsTrackRef = useRef(null);

  useGSAP((gsap, ST) => {
    let clearingsCleanup;
    const tl = gsap.timeline({ delay: 0.2 });
    tl.fromTo(heroBadgeRef.current, { y: 20, opacity: 0 }, { y: 0, opacity: 1, duration: 0.7, ease: "expo.out" })
      .fromTo(heroTitleRef.current, { y: 64, opacity: 0, skewY: 2.5 }, { y: 0, opacity: 1, skewY: 0, duration: 1.1, ease: "expo.out" }, "-=.3")
      .fromTo(heroSubRef.current, { y: 28, opacity: 0 }, { y: 0, opacity: 1, duration: 0.8, ease: "expo.out" }, "-=.55")
      .fromTo(heroCtaRef.current, { y: 20, opacity: 0 }, { y: 0, opacity: 1, duration: 0.7, ease: "expo.out" }, "-=.4");

    gsap.to(".name-bg", {
      yPercent: 30, scale: 1.1, rotationX: 5, rotationY: 3, ease: "none",
      scrollTrigger: { trigger: "body", start: "top top", end: "bottom top", scrub: 2 }
    });
    gsap.to(".name-float-1", {
      xPercent: -20, yPercent: -15, rotation: -25, scale: 0.9, opacity: 0.03, ease: "none",
      scrollTrigger: { trigger: "body", start: "top top", end: "bottom top", scrub: 1.5 }
    });
    gsap.to(".name-float-2", {
      xPercent: 25, yPercent: 20, rotation: 20, scale: 1.2, opacity: 0.02, ease: "none",
      scrollTrigger: { trigger: "body", start: "top top", end: "bottom top", scrub: 1.8 }
    });
    gsap.to(heroTitleRef.current, { yPercent: -20, ease: "none", scrollTrigger: { trigger: heroRef.current, start: "top top", end: "bottom top", scrub: 1.8 } });
    document.querySelectorAll(".f-ring").forEach((el, i) => {
      gsap.to(el, { y: i % 2 === 0 ? -55 : 55, ease: "none", scrollTrigger: { trigger: heroRef.current, start: "top top", end: "bottom top", scrub: 1 + i * 0.2 } });
    });

    if (clearingsRef.current && clearingsRailRef.current && clearingsTrackRef.current) {
      const section = clearingsRef.current;
      const rail = clearingsRailRef.current;
      const track = clearingsTrackRef.current;
      const cards = Array.from(track.querySelectorAll(".forest-clearing-card"));

      const syncWidth = () => {
        const w = window.innerWidth;
        const gap = w < 768 ? 16 : 28;
        const visible = w < 768 ? 1 : w < 1100 ? 1.08 : 1.35;
        const cardW = Math.max(280, Math.floor((rail.clientWidth - gap * (visible - 1)) / visible));
        track.style.setProperty("--clearing-width", `${cardW}px`);
        rail.style.setProperty("--clearing-gap", `${gap}px`);
      };

      syncWidth();
      const ro = new ResizeObserver(syncWidth);
      ro.observe(rail);
      const mm = gsap.matchMedia();

      mm.add("(min-width: 768px)", () => {
        gsap.set(track, { x: 0 });
        const getDistance = () => Math.max(0, track.scrollWidth - rail.clientWidth);
        const tween = gsap.to(track, {
          x: () => -getDistance(),
          ease: "none",
          scrollTrigger: {
            trigger: section,
            start: "top 12%",
            end: () => `+=${Math.max(getDistance(), window.innerHeight * 0.75)}`,
            scrub: 1.4,
            pin: true,
            anticipatePin: 1,
            invalidateOnRefresh: true
          }
        });
        window.addEventListener("resize", syncWidth);
        return () => {
          window.removeEventListener("resize", syncWidth);
          tween.scrollTrigger?.kill();
          tween.kill();
        };
      });

      const clearingCards = section.querySelectorAll(".forest-clearing-card");
      if (clearingCards.length) {
        gsap.fromTo(clearingCards, { y: 40, opacity: 0 }, { y: 0, opacity: 1, stagger: 0.12, duration: 0.85, ease: "expo.out", scrollTrigger: { trigger: section, start: "top 80%" } });
      }

      clearingsCleanup = () => {
        ro.disconnect();
        mm.revert();
      };
    }

    if (aboutRef.current) {
      gsap.fromTo(aboutRef.current, { y: 36, opacity: 0 }, { y: 0, opacity: 1, duration: 0.9, ease: "expo.out", scrollTrigger: { trigger: aboutRef.current, start: "top 80%" } });
    }
    const leaves = servicesRef.current?.querySelectorAll(".forest-leaf-card");
    if (leaves) {
      gsap.fromTo(leaves, { y: 28, opacity: 0, rotate: -2 }, { y: 0, opacity: 1, rotate: 0, stagger: 0.1, duration: 0.75, ease: "expo.out", scrollTrigger: { trigger: servicesRef.current, start: "top 82%" } });
    }
    const skillNodes = document.querySelectorAll(".forest-skill-node");
    if (skillNodes.length) {
      gsap.fromTo(skillNodes, { x: -20, opacity: 0 }, { x: 0, opacity: 1, stagger: 0.08, duration: 0.7, ease: "expo.out", scrollTrigger: { trigger: "#skills", start: "top 82%" } });
    }
    const moss = document.querySelectorAll(".forest-moss-tile");
    if (moss.length) {
      gsap.fromTo(moss, { scale: 0.9, opacity: 0 }, { scale: 1, opacity: 1, stagger: 0.03, duration: 0.5, ease: "back.out(1.4)", scrollTrigger: { trigger: ".forest-moss-panel", start: "top 85%" } });
    }
    const trailStops = timelineRef.current?.querySelectorAll(".forest-trail-stop");
    if (trailStops) {
      gsap.fromTo(trailStops, { y: 24, opacity: 0 }, { y: 0, opacity: 1, stagger: 0.12, duration: 0.75, ease: "expo.out", scrollTrigger: { trigger: timelineRef.current, start: "top 84%" } });
    }
    gsap.fromTo(contactRef.current, { y: 28, opacity: 0 }, { y: 0, opacity: 1, duration: 0.9, ease: "expo.out", scrollTrigger: { trigger: contactRef.current, start: "top 86%" } });
    document.querySelectorAll(".gsap-h-f").forEach((el) => {
      gsap.fromTo(el, { clipPath: "inset(0 100% 0 0)", opacity: 0 }, { clipPath: "inset(0 0% 0 0)", opacity: 1, duration: 1.1, ease: "expo.inOut", scrollTrigger: { trigger: el, start: "top 88%", toggleActions: "play none none none" } });
    });

    return clearingsCleanup;
  }, []);

  return (
    <>
      <div style={{ position: "fixed", inset: 0, pointerEvents: "none", zIndex: 0 }}>
        <div className="name-bg" style={{
          position: "absolute", top: "50%", left: "50%", transform: "translate(-50%, -50%)",
          fontSize: "clamp(130px,20vw,440px)", fontWeight: 900, fontFamily: "'Syne', sans-serif",
          color: theme.accent, opacity: 0.05, filter: "blur(3px)", letterSpacing: "-0.03em",
          whiteSpace: "nowrap", textTransform: "uppercase"
        }}>GAITHO</div>
        <div className="name-float-1" style={{
          position: "absolute", top: "20%", left: "10%", fontSize: "clamp(45px,6vw,120px)",
          fontWeight: 800, fontFamily: "'Syne', sans-serif", color: theme.animOrb, opacity: 0.06,
          filter: "blur(2px)", transform: "rotate(-15deg)"
        }}>MICHAEL</div>
        <div className="name-float-2" style={{
          position: "absolute", bottom: "25%", right: "15%", fontSize: "clamp(40px,6vw,100px)",
          fontWeight: 700, fontFamily: "'Space Mono', monospace", color: theme.animDot, opacity: 0.05,
          filter: "blur(2.5px)", transform: "rotate(5deg)"
        }}>DEVELOPER</div>
      </div>

      <div style={{ position: "relative", zIndex: 1 }}>
        {/* HERO — asymmetric clearing */}
        <section ref={heroRef} id="hero" className="forest-hero" style={{
          minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center",
          padding: "100px 40px 120px", position: "relative", overflow: "hidden",
          clipPath: "ellipse(120% 100% at 50% 0%)"
        }}>
          <ParallaxElement theme={theme} speed={0.3}>
            <ParticleCanvas theme={theme} />
            <div style={{
              position: "absolute", inset: 0, pointerEvents: "none",
              backgroundImage: `linear-gradient(${theme.animFg} 1px,transparent 1px),linear-gradient(90deg,${theme.animFg} 1px,transparent 1px)`,
              backgroundSize: "64px 64px",
              maskImage: "radial-gradient(ellipse 75% 75% at 50% 50%,black 20%,transparent 100%)",
              WebkitMaskImage: "radial-gradient(ellipse 75% 75% at 50% 50%,black 20%,transparent 100%)"
            }} />
            {[360, 200, 140, 260, 110].map((s, i) => (
              <div key={i} className="f-ring" style={{
                position: "absolute", width: s, height: s,
                borderRadius: `${[48, 62, 55, 70, 58][i]}% ${[52, 38, 45, 30, 42][i]}% ${[44, 60, 50, 66, 52][i]}% ${[56, 40, 50, 34, 48][i]}%`,
                border: `1px solid ${theme.animDot}`,
                left: ["5%", "68%", "6%", "62%", "41%"][i], top: ["7%", "12%", "58%", "50%", "73%"][i],
                pointerEvents: "none", opacity: 0.5,
                animation: [`spinSlow 30s linear infinite`, `spinSlowR 40s linear infinite`, `spinSlow 36s linear infinite`, `spinSlowR 50s linear infinite`, `spinSlow 24s linear infinite`][i]
              }} />
            ))}
            <div style={{
              position: "absolute", width: 480, height: 480, borderRadius: "50%",
              background: `radial-gradient(circle,${theme.animOrb} 0%,transparent 68%)`,
              top: "50%", left: "50%", transform: "translate(-50%,-50%)",
              animation: "breathe 6s ease-in-out infinite", pointerEvents: "none"
            }} />
          </ParallaxElement>

          <div className="forest-hero-inner">
            <div className="forest-hero-copy">
              <div ref={heroBadgeRef} style={{
                display: "inline-flex", alignItems: "center", gap: 7,
                border: `1px solid ${theme.border}`, borderRadius: 99, padding: "6px 16px", marginBottom: 26,
                background: theme.surfaceAlt, backdropFilter: "blur(14px)", fontSize: 14,
                letterSpacing: ".14em", textTransform: "uppercase", color: theme.text, opacity: 0.9
              }}>
                <span style={{ width: 6, height: 6, borderRadius: "50%", background: theme.accent, display: "inline-block", opacity: 0.65, animation: "pulse 2.8s ease-in-out infinite" }} />
                Open to Opportunities
              </div>
              <h1 ref={heroTitleRef} className="hero-title" style={{
                fontFamily: "'Syne',sans-serif", fontSize: "clamp(42px,7vw,84px)", fontWeight: 800,
                lineHeight: 1.02, letterSpacing: "-.03em", marginBottom: 12, color: theme.text, opacity: 0.9
              }}>
                Michael<br /><span style={{ color: theme.accent, opacity: 0.85 }}>Gaitho</span>
              </h1>
              <div ref={heroSubRef} className="hero-subtitle" style={{ fontFamily: "'Space Mono',monospace", fontSize: "clamp(13px,1.8vw,17px)", marginBottom: 28, minHeight: 26 }}>
                <Typewriter words={["Frontend Developer", "UI/UX Designer", "Creative Coder", "Problem Solver"]} theme={theme} />
              </div>
              <p className="hero-description" style={{ fontSize: 16, color: theme.textMuted, maxWidth: 460, margin: "0 0 32px", lineHeight: 1.9, opacity: 0.85 }}>
                Building premium digital experiences — Nakuru, Kenya
              </p>
              <div ref={heroCtaRef} className="hero-cta" style={{ display: "flex", gap: 11, flexWrap: "wrap" }}>
                <button className="bp" onClick={() => scrollTo("projects")}>Explore Clearings ↓</button>
                <button className="bg" onClick={() => scrollTo("contact")}>Let's Build</button>
              </div>
            </div>

            <div className="forest-hero-orbit" aria-hidden="true">
              <div className="forest-orbit-ring" style={{ width: 320, height: 320, animation: "spinSlow 34s linear infinite" }} />
              <div className="forest-orbit-ring" style={{ width: 400, height: 400, animation: "spinSlowR 42s linear infinite", opacity: 0.6 }} />
              <div className="forest-orbit-core">
                <span className="forest-orbit-stat">6+</span>
                <span className="forest-orbit-label">Core Skills</span>
                <span className="forest-orbit-stat" style={{ fontSize: "clamp(22px,3vw,32px)", marginTop: 8 }}>{PROJECTS.length}</span>
                <span className="forest-orbit-label">Live Projects</span>
              </div>
            </div>
          </div>
          {devMode && <DevBadge id="hero" devMode={devMode} theme={theme} />}
        </section>

        {/* Canopy stream */}
        <div className="forest-canopy-stream" style={{ overflow: "hidden", background: theme.bg, borderTop: `1px solid ${theme.border}`, borderBottom: `1px solid ${theme.border}` }}>
          <div style={{ display: "flex", gap: 30, whiteSpace: "nowrap", animation: "marquee 22s linear infinite" }}>
            {[...TECH, ...TECH].map((t, i) => (
              <span key={i} style={{ fontSize: 14, fontWeight: 600, letterSpacing: ".15em", textTransform: "uppercase", color: theme.text, opacity: 0.6 }}>
                {t.name}<span style={{ marginLeft: 16, opacity: 0.25 }}>·</span>
              </span>
            ))}
          </div>
        </div>

        {/* PROJECTS FIRST — horizontal clearings */}
        <section ref={clearingsRef} id="projects" className="forest-clearings">
          <div className="forest-clearings-head">
            <span className="sec-label">Trail Marker 01</span>
            <h2 className={clsx("gsap-h-f", "section-title")} style={{ fontFamily: "'Syne',sans-serif", fontSize: "clamp(30px,4vw,48px)", fontWeight: 800, letterSpacing: "-.02em", margin: "8px 0 12px", color: theme.text }}>
              Project Clearings
            </h2>
            <p style={{ fontSize: 15, color: theme.textMuted, lineHeight: 1.75, maxWidth: 560, opacity: 0.85 }}>
              Walk through live builds — each clearing opens into a deployed interface.
            </p>
          </div>
          <div ref={clearingsRailRef} className="forest-clearings-rail">
            <div ref={clearingsTrackRef} className="forest-clearings-track">
              {PROJECTS.map((project, i) => (
                <ForestClearingCard key={project.id} project={project} index={i} theme={theme} />
              ))}
            </div>
          </div>
          <p className="forest-clearings-hint">Scroll to walk the trail →</p>
          {devMode && <DevBadge id="projects" devMode={devMode} theme={theme} />}
        </section>

        {/* GROVE — about + services bento */}
        <section className="forest-grove">
          <div className="forest-grove-shell">
            <div ref={aboutRef} id="about" className="forest-grove-about">
              <div className="forest-grove-portrait">◌</div>
              <span className="sec-label">The Grove</span>
              <h2 className="gsap-h-f" style={{ fontFamily: theme.headingFont, fontSize: "clamp(28px,3.5vw,40px)", fontWeight: 800, lineHeight: 1.15, letterSpacing: "-.02em", marginBottom: 16, color: theme.text }}>
                Crafting interfaces<br /><span style={{ color: theme.accent, opacity: 0.82 }}>worth remembering</span>
              </h2>
              <p style={{ color: theme.textMuted, lineHeight: 1.9, marginBottom: 12, fontSize: 15 }}>
                Frontend Developer & UI/UX designer specializing in AI-powered interfaces and real-time analytics.
              </p>
              <p style={{ color: theme.textMuted, lineHeight: 1.9, marginBottom: 0, fontSize: 15 }}>
                Bachelor of IT student, blending academic rigour with real-world craft.
              </p>
              <div className="forest-grove-meta">
                <span className="forest-grove-chip">Nakuru, Kenya</span>
                <span className="forest-grove-chip">AI Interfaces</span>
                <span className="forest-grove-chip">Design + Code</span>
              </div>
              <div style={{ display: "flex", gap: 11, flexWrap: "wrap" }}>
                <button className="bp" onClick={() => window.open("/resume.pdf", "_blank")}>Download Resume</button>
                <button className="bg" onClick={() => scrollTo("projects")}>See Clearings</button>
              </div>
              {devMode && <DevBadge id="about" devMode={devMode} theme={theme} />}
            </div>

            <div ref={servicesRef} id="services" className="forest-grove-services">
              <div style={{ gridColumn: "1 / -1", marginBottom: 4 }}>
                <span className="sec-label">What Grows Here</span>
                <h3 className="gsap-h-f" style={{ fontFamily: "'Syne',sans-serif", fontSize: "clamp(22px,3vw,32px)", fontWeight: 800, margin: "6px 0 14px", color: theme.text }}>Services</h3>
              </div>
              {SERVICES.map((s) => (
                <div key={s.title} className="forest-leaf-card srv-card">
                  <div className="forest-leaf-icon">{s.icon}</div>
                  <h3>{s.title}</h3>
                  <p>{s.desc}</p>
                </div>
              ))}
              {devMode && <DevBadge id="services" devMode={devMode} theme={theme} />}
            </div>
          </div>
        </section>

        {/* CANOPY — skills trail + moss tech */}
        <section id="skills" className="forest-canopy">
          <ScrollReveal theme={theme} direction="up" delay={0.15}>
            <div className="forest-canopy-inner">
              <div>
                <span className="sec-label">Trail Marker 02</span>
                <h2 className={clsx("gsap-h-f", "section-title")} style={{ fontFamily: "'Syne',sans-serif", fontSize: "clamp(28px,4vw,42px)", fontWeight: 800, letterSpacing: "-.02em", margin: "8px 0 28px", color: theme.text }}>
                  Growth Rings
                </h2>
                <div className="forest-growth-trail">
                  {SKILLS.map((s, i) => (
                    <div key={s.label} className="forest-skill-node">
                      <SkillBar {...s} theme={theme} delay={i * 0.06} />
                    </div>
                  ))}
                </div>
              </div>
              <div className="forest-moss-panel">
                <h3 style={{ fontFamily: "'Syne',sans-serif", fontSize: 17, fontWeight: 700, marginBottom: 18, color: theme.textMuted, letterSpacing: ".08em", textTransform: "uppercase", opacity: 0.8 }}>
                  Tech Moss
                </h3>
                <div className="forest-moss-grid">
                  {TECH.map((t) => (
                    <div key={t.name} className="forest-moss-tile">
                      <img src={t.colorLogo} alt={t.name} />
                      <span>{t.name}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </ScrollReveal>
          {devMode && <DevBadge id="skills" devMode={devMode} theme={theme} />}
        </section>

        {/* TRAIL — horizontal timeline */}
        <section ref={timelineRef} id="experience" className="forest-trail">
          <div className="forest-trail-head">
            <span className="sec-label">Trail Marker 03</span>
            <h2 className={clsx("gsap-h-f", "section-title")} style={{ fontFamily: "'Syne',sans-serif", fontSize: "clamp(28px,4vw,42px)", fontWeight: 800, letterSpacing: "-.02em", color: theme.text }}>
              The Path So Far
            </h2>
          </div>
          <div className="forest-trail-rail">
            <div className="forest-trail-track">
              {TIMELINE.map((t, i) => (
                <div key={i} className="forest-trail-stop tl-item">
                  <div className="forest-trail-node">{t.type === "edu" ? "◦" : "■"}</div>
                  <div className="forest-trail-year">{t.year} · {t.place}</div>
                  <h3>{t.title}</h3>
                  <p>{t.desc}</p>
                </div>
              ))}
            </div>
          </div>
          {devMode && <DevBadge id="experience" devMode={devMode} theme={theme} />}
        </section>

        {/* CONTACT — orbital clearing */}
        <section ref={contactRef} id="contact" className="forest-contact">
          <ScrollReveal theme={theme} direction="up" delay={0.3}>
            <div className="forest-contact-shell">
              <span className="sec-label">Final Clearing</span>
              <h2 className={clsx("gsap-h-f", "section-title")} style={{ fontFamily: "'Syne',sans-serif", fontSize: "clamp(28px,4vw,42px)", fontWeight: 800, letterSpacing: "-.02em", color: theme.text }}>
                Let's Work Together
              </h2>
              <p style={{ fontSize: 15, lineHeight: 1.8, color: theme.text, opacity: 0.8, maxWidth: 520, margin: "14px auto 0" }}>
                I'm always interested in hearing about new projects and opportunities.
              </p>

              <div className="forest-contact-orbit">
                {CONTACT_INFO.map((c, i) => (
                  <a
                    key={i}
                    className="forest-contact-orb contact-card"
                    href={c.link}
                    onClick={(e) => { if (c.action === "scroll") { e.preventDefault(); scrollTo("contact"); } }}
                    target={c.action === "scroll" ? "_self" : "_blank"}
                    rel="noopener noreferrer"
                  >
                    <div className="contact-icon" style={{ fontSize: 22, marginBottom: 8, opacity: 0.7 }}>{c.icon}</div>
                    <div className="contact-title" style={{ fontSize: 14, fontWeight: 700, fontFamily: "'Syne',sans-serif", marginBottom: 4 }}>{c.title}</div>
                    <div className="contact-value" style={{ fontSize: 11, opacity: 0.7 }}>{c.value}</div>
                  </a>
                ))}
              </div>

              <div className="forest-contact-form-wrap contact-form">
                {sent ? (
                  <div style={{ textAlign: "center", padding: "24px 0" }}>
                    <div style={{ fontSize: 24, marginBottom: 16, opacity: 0.6 }}>✓</div>
                    <h3 style={{ fontFamily: "'Syne',sans-serif", fontSize: 20, fontWeight: 800, color: theme.text }}>Message Sent!</h3>
                    <p style={{ color: theme.textMuted, fontSize: 14 }}>Michael will reply shortly.</p>
                  </div>
                ) : (
                  <>
                    {[{ l: "Name", k: "name", t: "text", p: "Your name" }, { l: "Email", k: "email", t: "email", p: "hello@example.com" }, { l: "Subject", k: "subject", t: "text", p: "Project Inquiry" }].map((f) => (
                      <div key={f.k} style={{ marginBottom: 14 }}>
                        <label className="form-label" style={{ display: "block", fontSize: 12, fontWeight: 700, letterSpacing: ".14em", textTransform: "uppercase", color: theme.text, marginBottom: 5, fontFamily: "'Space Mono',monospace", opacity: 0.8 }}>{f.l}</label>
                        <input className="form-input" style={{ width: "100%", padding: "12px 14px", background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: "12px 3px 12px 3px", color: theme.text, fontSize: 15, fontFamily: "'DM Sans',sans-serif", outline: "none" }} type={f.t} placeholder={f.p} value={form[f.k]} onChange={(e) => setForm((d) => ({ ...d, [f.k]: e.target.value }))} />
                      </div>
                    ))}
                    <div style={{ marginBottom: 20 }}>
                      <label className="form-label" style={{ display: "block", fontSize: 12, fontWeight: 700, letterSpacing: ".14em", textTransform: "uppercase", color: theme.text, marginBottom: 5, fontFamily: "'Space Mono',monospace", opacity: 0.8 }}>Message</label>
                      <textarea className="form-textarea" style={{ width: "100%", padding: "12px 14px", background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: "12px 3px 12px 3px", color: theme.text, fontSize: 15, fontFamily: "'DM Sans',sans-serif", outline: "none", resize: "vertical" }} rows={5} placeholder="Tell me about your project..." value={form.message} onChange={(e) => setForm((d) => ({ ...d, message: e.target.value }))} />
                    </div>
                    <button className={clsx("bp", "form-button")} onClick={() => {
                      const subject = encodeURIComponent(form.subject || "Portfolio Contact");
                      const body = encodeURIComponent(`Name: ${form.name}\nEmail: ${form.email}\n\n${form.message}`);
                      window.open(`mailto:michaelgaitho47@gmail.com?subject=${subject}&body=${body}`);
                      setSent(true);
                    }} style={{ width: "100%", display: "flex", justifyContent: "center", fontSize: 14, padding: "14px", borderRadius: "12px 3px 12px 3px" }}>
                      Send Message →
                    </button>
                  </>
                )}
              </div>
            </div>
          </ScrollReveal>
          {devMode && <DevBadge id="contact" devMode={devMode} theme={theme} />}
        </section>
      </div>
    </>
  );
}
